package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.util.HashMap;
import java.util.Map;

import org.jsoup.parser.ParseSettings;
import org.jsoup.parser.Parser;
import javax.annotation.Nullable;
import java.io.IOException;

public class CommentTest {

    @Test
    public void constructorWithDataIsInitialized() {
        String data = "test";
        Comment comment = new Comment(data);
        assertEquals(data, comment.getData());
    }

    @Test
    public void nodeNameIsCommentWhenNoDataIsProvided() {
        Comment comment = new Comment("");
        assertEquals("comment", comment.nodeName());
    }

    @Test
    public void nodeNameIsCommentWithProvidedData() {
        String data = "test";
        Comment comment = new Comment(data);
        assertEquals("comment-" + data, comment.nodeName());
    }

    @Test
    public void getDataReturnsProvidedString() {
        String data = "test";
        Comment comment = new Comment(data);
        assertEquals(data, comment.getData());
    }

    @Test
    public void setDataSetsNewDataForComment() {
        String oldData = "old";
        String newData = "new";
        Comment comment = new Comment(oldData);
        comment.setData(newData);
        assertNotEquals(oldData, comment.getData());
        assertEquals(newData, comment.getData());
    }

    @Test
    public void outerHtmlHeadAccumulatesEmptyString() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        int depth = 0;
        Document.OutputSettings outSettings = new Document.OutputSettings();
        Comment comment = new Comment("");
        comment.outerHtmlHead(accum, depth, outSettings);
        assertEquals("", out.toString());
    }

    @Test
    public void outerHtmlTailAccumulatesEmptyString() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        int depth = 0;
        Document.OutputSettings outSettings = new Document.OutputSettings();
        Comment comment = new Comment("");
        comment.outerHtmlTail(accum, depth, outSettings);
        assertEquals("", out.toString());
    }

    @Test
    public void outerHtmlHeadAndTailDoNotOverlap() {
        ByteArrayOutputStream out1 = new ByteArrayOutputStream();
        Appendable accum1 = out1;
        int depth1 = 0;
        Document.OutputSettings outSettings1 = new Document.OutputSettings();
        Comment comment1 = new Comment("");
        comment1.outerHtmlHead(accum1, depth1, outSettings1);

        ByteArrayOutputStream out2 = new ByteArrayOutputStream();
        Appendable accum2 = out2;
        int depth2 = 0;
        Document.OutputSettings outSettings2 = new Document.OutputSettings();
        Comment comment2 = new Comment("");
        comment2.outerHtmlTail(accum2, depth2, outSettings2);

        assertEquals("", out1.toString());
        assertEquals("", out2.toString());
    }

    @Test
    public void toStringIsCommentTagWithData() {
        String data = "test";
        Comment comment = new Comment(data);
        assertTrue(comment.toString().contains("<comment>");
        assertTrue(comment.toString().contains("data=\""));
        assertTrue(comment.toString().contains("\""));
        assertEquals("test", comment.toString().split("\"")[1].trim());
    }

    @Test
    public void cloneReturnsNewCommentWithSameData() {
        String data = "test";
        Comment comment = new Comment(data);
        Comment clonedComment = comment.clone();
        assertEquals(comment.getData(), clonedComment.getData());
    }

    @Test
    public void isXmlDeclarationIsFalseForAllComments() {
        boolean result1 = new Comment("").isXmlDeclaration();
        assertTrue(result1);

        boolean result2 = new Comment("test").isXmlDeclaration();
        assertTrue(result2);
    }

    @Test
    public void asXmlDeclarationReturnsNullWhenCommentHasNoData() {
        Comment comment = new Comment("");
        assertNull(comment.asXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsValidXmlDeclarationForEmptyStringData() {
        String data = "";
        XmlDeclaration xmlDeclaration = comment.asXmlDeclaration();
        assertNotNull(xmlDeclaration);
        assertTrue(xmlDeclaration.toString().equals("<?xml declaration public \"\" \"UTF-8\"?>"));
    }
